CROP_TEMPLATES = [
    ("potato","Markies","Season A",2023), ("potato","Shangi","Season B",2023),
    ("maize","DK8031","Season A",2023), ("maize","RWILI","Season B",2022),
    ("bean","Lyamungu","Season B",2022), ("bean","Urwintore","Season A",2023),
    ("coffee","Red Bourbon","Annual",2023),
]

async def seed():
    await init_db()
    random.seed(42)
    async with AsyncSessionLocal() as session:
        for d_data in DISTRICTS:
            session.add(District(**d_data))
        await session.flush()
        from sqlalchemy import select
        result = await session.execute(select(District))
        districts = result.scalars().all()
        for d in districts:
            for crop, variety, season, year in CROP_TEMPLATES:
                if crop == "coffee" and not d.coffee_suitable: continue
                base = {"potato": d.avg_potato_yield or 12, "maize": d.avg_maize_yield or 3,
                        "bean": d.avg_bean_yield or 1.5, "coffee": d.avg_coffee_yield or 0.8}.get(crop, 3.0)
                noise = random.uniform(0.85, 1.15)
                session.add(CropTrial(district_id=d.id, crop=crop, variety=variety, season=season, year=year,
                                      soil_ph_trial=d.soil_ph, rainfall_season_mm=d.rainfall_annual_mm/2,
                                      temp_mean_trial=d.temp_mean_c, humidity_trial=d.humidity_pct,
                                      ndvi_at_planting=d.ndvi_mean, yield_t_ha=round(base*noise, 1),
                                      performance_score=round(min(100, base*noise/(base*1.15)*100))))
        for d in districts:
            for year in [2022, 2023]:
                for month in range(1, 13):
                    rf = 1.3 if month in (3,4,5,9,10,11) else 0.6
                    session.add(ClimateRecord(district_id=d.id, year=year, month=month,
                                              rainfall_mm=round(d.rainfall_annual_mm/12*rf*random.uniform(0.7,1.3),1),
                                              temp_mean_c=round(d.temp_mean_c+random.uniform(-1.5,1.5),1),
                                              temp_max_c=round(d.temp_max_c+random.uniform(-1,1),1),
                                              temp_min_c=round(d.temp_min_c+random.uniform(-1,1),1),
                                              humidity_pct=round(d.humidity_pct+random.uniform(-5,5),1),
                                              ndvi=round(d.ndvi_mean+random.uniform(-0.05,0.05),3),
                                              drought_score=max(0,min(100,d.drought_risk_score+random.uniform(-15,15))),
                                              heat_stress_score=max(0,d.temp_mean_c-20)*5,
                                              flood_risk_score=d.flood_risk_score*rf*random.uniform(0.8,1.2)))
        await session.commit()
        print(f"✓ Seeded {len(DISTRICTS)} districts + crop trials + 24 months climate data.")

if __name__ == "__main__":
    asyncio.run(seed())
